#!/usr/bin/env node

import process from "node:process";
import { CommanderError } from "commander";
import { isMainModule } from "../../shared/src/node/main-module.ts";
import {
  decisionFailure
} from "./application-result.ts";
import {
  createCliProgram,
  type CliArgs,
  type Command
} from "./cli-args.ts";
import {
  printActivationCandidateWarnings,
  printDecisionFailure,
  printDecisionQuerySuccess
} from "./cli-output.ts";
import {
  prepareDecisionLifecycle,
  type DecisionLifecycleRequest
} from "./decision-lifecycle-service.ts";
import {
  executeDecisionQuery,
  type DecisionLocation,
  type DecisionQueryRequest
} from "./decision-query-service.ts";
import {
  applyDecisionChanges
} from "./decision-transaction.ts";
import {
  loadDecisionValidationContext,
  validateDecisionRecords,
  type DecisionValidationOptions
} from "./index.ts";
import { scanDecisionRecords } from "./scan.ts";
import {
  compareDecisionRecords,
  type DecisionAlignment,
  type DecisionScan,
  type DecisionScanOptions
} from "./types.ts";

type CommandHandler = (args: CliArgs) => Promise<number>;

async function runQuery(request: DecisionQueryRequest): Promise<number> {
  const result = await executeDecisionQuery(request);
  if (result.status === "error") {
    printDecisionFailure(result);
    return result.exitCode;
  }
  printDecisionQuerySuccess(result);
  return 0;
}

async function runDomains(args: CliArgs): Promise<number> {
  return await runQuery({
    command: "domains",
    location: decisionLocation(args)
  });
}

async function runCheck(args: CliArgs): Promise<number> {
  return await runQuery({
    command: "check",
    location: decisionLocation(args)
  });
}

async function runList(args: CliArgs): Promise<number> {
  return await runQuery({
    alignment: args.alignment,
    command: "list",
    domain: args.domain,
    fullTime: args.fullTime,
    location: decisionLocation(args),
    status: args.status
  });
}

async function runShow(args: CliArgs): Promise<number> {
  return await runQuery({
    command: "show",
    location: decisionLocation(args),
    recordPath: args.recordPaths[0] ?? ""
  });
}

async function runTrace(args: CliArgs): Promise<number> {
  return await runQuery({
    command: "trace",
    direction: args.traceDirection,
    location: decisionLocation(args),
    maxDepth: args.traceDepth,
    recordPath: args.recordPaths[0] ?? ""
  });
}

async function runSyncIndex(args: CliArgs): Promise<number> {
  return await runQuery({
    command: "sync-index",
    location: decisionLocation(args),
    write: args.write
  });
}

async function runActivate(args: CliArgs): Promise<number> {
  return await runActivation(args, "activate");
}

async function runEvolve(args: CliArgs): Promise<number> {
  return await runActivation(args, "evolve");
}

async function runActivation(
  args: CliArgs,
  action: "activate" | "evolve"
): Promise<number> {
  if (action === "evolve" && args.relations.length === 0) {
    printDecisionFailure(decisionFailure(
      ["evolve requires at least one --relation."],
      { presentation: "plain" }
    ));
    return 1;
  }
  const alignment: DecisionAlignment | null = args.alignment === "all"
    ? null
    : args.alignment;
  if (alignment === null) {
    printDecisionFailure(decisionFailure(
      [`${action} requires --alignment aligned or unaligned.`],
      { presentation: "plain" }
    ));
    return 1;
  }
  const scan = await loadLifecycleScan(args, {
    allowEmptyDecisionSet: true,
    scanErrorPolicy: "allow-activation-candidates"
  });
  if (scan === null) {
    return 1;
  }
  return await applyLifecycle(args, scan, {
    action,
    alignment,
    recordPath: args.recordPaths[0] ?? "",
    relations: args.relations
  });
}

async function runMarkAligned(args: CliArgs): Promise<number> {
  return await runValidatedMaintenance(args, {
    action: "mark-aligned",
    recordPath: args.recordPaths[0] ?? ""
  });
}

async function runArchive(args: CliArgs): Promise<number> {
  return await runValidatedMaintenance(args, {
    action: "archive",
    recordPaths: args.recordPaths
  });
}

async function runValidatedMaintenance(
  args: CliArgs,
  request: DecisionLifecycleRequest
): Promise<number> {
  const scan = await loadLifecycleScan(args, {
    checkIndexText: false,
    scanErrorPolicy: "source-only"
  });
  return scan === null ? 1 : await applyLifecycle(args, scan, request);
}

async function runDiscard(args: CliArgs): Promise<number> {
  const { result } = await loadDecisionValidationContext(
    decisionScanOptions(args),
    { checkIndexText: false }
  );
  return await applyLifecycle(args, result.scan, {
    action: "discard",
    recordPath: args.recordPaths[0] ?? ""
  });
}

async function loadLifecycleScan(
  args: CliArgs,
  validationOptions: DecisionValidationOptions
): Promise<DecisionScan | null> {
  const { result } = await loadDecisionValidationContext(
    decisionScanOptions(args),
    validationOptions
  );
  if (result.errors.length > 0) {
    printDecisionFailure(decisionFailure(result.errors));
    return null;
  }
  return result.scan;
}

async function applyLifecycle(
  args: CliArgs,
  scan: DecisionScan,
  request: DecisionLifecycleRequest
): Promise<number> {
  const prepared = await prepareDecisionLifecycle(scan, request);
  if (prepared.status === "error") {
    printDecisionFailure(prepared);
    return prepared.exitCode;
  }
  const errors = await applyDecisionChanges({
    changes: prepared.changes,
    originalScan: scan,
    scanOptions: decisionScanOptions(args)
  });
  if (errors.length > 0) {
    printDecisionFailure(decisionFailure(errors));
    return 1;
  }
  console.log(prepared.message);
  const updatedScan = await scanDecisionRecords(decisionScanOptions(args));
  printActivationCandidateWarnings(
    updatedScan.records
      .filter((record) => record.activationCandidate)
      .sort(compareDecisionRecords)
      .map((record) => record.relativePath)
  );
  return 0;
}

function decisionLocation(args: CliArgs): DecisionLocation {
  return {
    decisionsDir: args.decisionsDir,
    workspaceRoot: args.workspaceRoot
  };
}

function decisionScanOptions(args: CliArgs): DecisionScanOptions {
  return decisionLocation(args);
}

const commandHandlers: Record<Command, CommandHandler> = {
  activate: runActivate,
  archive: runArchive,
  check: runCheck,
  discard: runDiscard,
  domains: runDomains,
  evolve: runEvolve,
  list: runList,
  "mark-aligned": runMarkAligned,
  show: runShow,
  "sync-index": runSyncIndex,
  trace: runTrace
};

export async function runDecisionRecordsCli(
  argv: readonly string[] = process.argv.slice(2)
): Promise<number> {
  let exitCode = 0;
  const program = createCliProgram(
    async (args) => await commandHandlers[args.command](args),
    (value) => {
      exitCode = value;
    }
  );

  try {
    await program.parseAsync(["node", "decision-records.mjs", ...argv]);
  } catch (error) {
    if (error instanceof CommanderError) {
      return error.exitCode === 0 ? 0 : 2;
    }
    printDecisionFailure(decisionFailure([
      "Unexpected decision records command failure: " + errorText(error)
    ]));
    return 1;
  }
  return exitCode;
}

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export { scanDecisionRecords, validateDecisionRecords };
export type { DecisionDomainDefinition } from "./decision-domain-catalog.ts";
export type {
  DecisionAlignment,
  DecisionDocument,
  DecisionIndex,
  DecisionIndexEntry,
  DecisionIndexMetadata,
  DecisionIndexState,
  DecisionListAlignment,
  DecisionListStatus,
  DecisionMetadata,
  DecisionProjection,
  DecisionRecord,
  DecisionRelation,
  DecisionRelationType,
  DecisionScan,
  DecisionScanOptions,
  DecisionStatus,
  DecisionValidationResult
} from "./types.ts";

if (isMainModule(import.meta.url)) {
  process.exitCode = await runDecisionRecordsCli();
}
